import { colors, useTheme } from '@/theme'
import { LinearGradient } from 'expo-linear-gradient'
import Animated, { LinearTransition } from 'react-native-reanimated'
import { RevealingTranscript } from './RevealingTranscript'
import { defineStyles } from '@/utils/defineStyles'
import { LayoutChangeEvent } from 'react-native'
import { useState } from 'react'

type TranscriptViewProps = {
	prompt: string
	isTransferred: boolean
	withGradient: boolean
}

export const TranscriptView = ({
	prompt,
	isTransferred,
	withGradient
}: TranscriptViewProps) => {
	const { theme } = useTheme()
	const [parentHeight, setParentHeight] = useState(0)

	const handleLayout = (event: LayoutChangeEvent) => {
		const { height } = event.nativeEvent.layout
		setParentHeight(height)
	}

	return (
		<Animated.View
			layout={LinearTransition.springify().damping(18).stiffness(140)}
			style={styles.transcriptContainer}
			onLayout={handleLayout}
		>
			{withGradient && (
				<LinearGradient
					colors={[
						`${colors[theme].background}FF`,
						`${colors[theme].background}00`
					]}
					style={styles.gradientOverlay}
				/>
			)}
			<RevealingTranscript
				prompt={prompt}
				isTransferred={isTransferred}
				parentHeight={parentHeight}
			/>
		</Animated.View>
	)
}

const styles = defineStyles({
	transcriptContainer: {
		maxHeight: '85%',
		minHeight: '30%',
		justifyContent: 'flex-end',
		position: 'relative',
		overflow: 'hidden',
		marginBottom: 24,
		zIndex: 1
	},
	gradientOverlay: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		height: '45%',
		zIndex: 2
	}
})
